package edu.casestudy.merkle.core;
import java.nio.charset.StandardCharsets; import java.security.*; import java.util.HexFormat;
public final class HashUtils { private HashUtils(){} public static byte[] hash(byte... b){try{return MessageDigest.getInstance("SHA-256").digest(b);}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} public static byte[] parent(byte[] l,byte[] r){byte[] b=new byte[65];b[0]=1;System.arraycopy(l,0,b,1,32);System.arraycopy(r,0,b,33,32);return hash(b);} public static byte[] leaf(byte[] b){byte[] v=new byte[b.length+1];System.arraycopy(b,0,v,1,b.length);return hash(v);} public static String hex(byte[] b){return HexFormat.of().formatHex(b);} public static byte[] unhex(String h){if(h==null||!h.matches("[0-9a-fA-F]{64}"))throw new IllegalArgumentException("Expected SHA-256 hex");return HexFormat.of().parseHex(h);} public static byte[] empty(){return hash(new byte[]{2});} public static byte[] utf8(String s){return s.getBytes(StandardCharsets.UTF_8);} }
